  const saved = await K.disk('zz-textkeys-rt');
  K.ok(saved === file && !st.canUndo && !st.dirty, 'saved unchanged (Save As): the same bytes, no key added');
  // a level from before keys: Emberfall without its keys and tags, written under the temporary name and opened
  const bare = F.parseLevel(file).level;
  for (const o of bare.objects) {
    delete o.textKeys;
    for (const f of ['talk', 'run']) if (o[f] !== undefined) o[f] = TK.stripScriptTags(o[f]);
  }
  delete bare.textKeys;
  await S.saveProjectLevel('zz-textkeys-rt', bare);
  // (a file written moments ago: served from public/ once the dev server has seen it)
  for (let k = 0; k < 60; k++) { const r = await fetch('/levels/zz-textkeys-rt.json', { cache: 'no-store' }); if ((r.headers.get('content-type') ?? '').includes('json')) break; await T.sleep(100); }
